//! OFFLINE parity for the loader's pure builders against fixtures
//! generated by running the REAL ingest/loader.py functions
//! (fixtures/loader_parity_cases.json + loader_payloads.json — see
//! fixtures/gen_loader_parity.py).
//!
//! Everything must agree: row tuples (raw values included — a string
//! popularity builds a row on BOTH sides and only dies at the bind),
//! cast/crew filtering, rec rows, the completeness rule, the gate
//! matrix, and builder ERROR texts where deterministic (KeyError
//! `'id'`, the date-constructor messages from fromisoformat, ...).

use cine_rec_ingest::loader::{
    append_to_response, is_complete, keep_cast, keep_crew, rec_rows_from_payload, should_ingest,
    title_row_from_payload, tv_row_from_payload,
};
use cine_rec_ingest::pyval::PyConvError;
use serde_json::{json, Value};

fn cases() -> Value {
    serde_json::from_str(include_str!("fixtures/loader_parity_cases.json")).unwrap()
}

fn payloads() -> Value {
    serde_json::from_str(include_str!("fixtures/loader_payloads.json")).unwrap()
}

fn payload_of(name: &str) -> Value {
    payloads()["payloads"]
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["name"] == name)
        .unwrap_or_else(|| panic!("payload {name} missing"))["payload"]
        .clone()
}

/// Render a PyConvError the way the fixture records Python
/// exceptions: "Class: message".
fn err_string(e: &PyConvError) -> String {
    let class = match e {
        PyConvError::Key(_) => "KeyError",
        PyConvError::Value(_) => "ValueError",
        PyConvError::Type(_) => "TypeError",
        PyConvError::Attr(_) => "AttributeError",
    };
    format!("{class}: {e}")
}

fn check_result(got: Result<Vec<Value>, PyConvError>, want: &Value, ctx: &str) {
    match (got, want.get("ok"), want.get("error")) {
        (Ok(values), Some(expected), None) => {
            let expected = expected.as_array().unwrap();
            assert_eq!(values.len(), expected.len(), "{ctx}: tuple length differs");
            for (i, (g, w)) in values.iter().zip(expected).enumerate() {
                assert_eq!(g, w, "{ctx}: slot {i} differs\n  got  {g}\n  want {w}");
            }
        }
        (Err(e), None, Some(want)) => {
            assert_eq!(
                &err_string(&e),
                want.as_str().unwrap(),
                "{ctx}: error text drifted"
            );
        }
        (Ok(_), None, Some(want)) => {
            panic!(
                "{ctx}: built a row, Python raised {}",
                want.as_str().unwrap()
            )
        }
        (Err(e), Some(_), None) => panic!("{ctx}: raised {e}, Python built a row"),
        other => panic!("{ctx}: malformed expectation {other:?}"),
    }
}

fn movie_row_json(payload: &Value) -> Result<Vec<Value>, PyConvError> {
    let r = title_row_from_payload(payload)?;
    let date = |d: Option<chrono::NaiveDate>| match d {
        Some(d) => Value::String(d.to_string()),
        None => Value::Null,
    };
    Ok(vec![
        json!(r.id),
        r.title,
        clone(&r.original_title),
        clone(&r.original_language),
        clone(&r.overview),
        date(r.release_date),
        clone(&r.runtime),
        clone(&r.status),
        json!(r.adult),
        clone(&r.vote_average),
        clone(&r.vote_count),
        clone(&r.popularity),
        clone(&r.poster_path),
        clone(&r.backdrop_path),
        clone(&r.collection_id),
        clone(&r.imdb_id),
        clone(&r.budget),
        clone(&r.revenue),
    ])
}

fn tv_row_json(payload: &Value) -> Result<Vec<Value>, PyConvError> {
    let r = tv_row_from_payload(payload)?;
    let date = |d: Option<chrono::NaiveDate>| match d {
        Some(d) => Value::String(d.to_string()),
        None => Value::Null,
    };
    Ok(vec![
        json!(r.id),
        r.name,
        clone(&r.original_name),
        clone(&r.original_language),
        clone(&r.overview),
        date(r.first_air_date),
        date(r.last_air_date),
        clone(&r.status),
        clone(&r.in_production),
        clone(&r.number_of_seasons),
        clone(&r.number_of_episodes),
        json!(r.adult),
        clone(&r.vote_average),
        clone(&r.vote_count),
        clone(&r.popularity),
        clone(&r.poster_path),
        clone(&r.backdrop_path),
        clone(&r.imdb_id),
    ])
}

fn clone(v: &Option<Value>) -> Value {
    v.clone().unwrap_or(Value::Null)
}

#[test]
fn builders_match_python_row_for_row() {
    let doc = cases();
    let case_list = doc["cases"].as_array().unwrap();
    assert!(case_list.len() >= 14, "only {} cases", case_list.len());

    for case in case_list {
        let name = case["name"].as_str().unwrap();
        let payload = payload_of(name);

        if let Some(want) = case.get("movie_row") {
            check_result(movie_row_json(&payload), want, &format!("{name}.movie_row"));
        }
        if let Some(want) = case.get("tv_row") {
            check_result(tv_row_json(&payload), want, &format!("{name}.tv_row"));
        }

        // keep_cast / keep_crew over the same credits the generator
        // fed Python.
        let credits = payload.get("credits").cloned().unwrap_or(json!({}));
        let cast_list = credits
            .get("cast")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let crew_list = credits
            .get("crew")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let got_cast: Result<Vec<Value>, PyConvError> = keep_cast(&cast_list).map(|rows| {
            rows.iter()
                .map(|r| json!([r.person_id, r.character, r.cast_order]))
                .collect()
        });
        check_result(got_cast, &case["cast"], &format!("{name}.cast"));
        let got_crew: Result<Vec<Value>, PyConvError> = keep_crew(&crew_list).map(|rows| {
            rows.iter()
                .map(|r| json!([r.person_id, r.job, clone(&r.department)]))
                .collect()
        });
        check_result(got_crew, &case["crew"], &format!("{name}.crew"));

        let got_recs: Result<Vec<Value>, PyConvError> =
            rec_rows_from_payload(&payload).map(|rows| {
                rows.iter()
                    .map(|r| {
                        json!([
                            r.media_id,
                            r.media_type,
                            r.rec_media_id,
                            r.rec_media_type,
                            r.rank,
                            r.popularity
                        ])
                    })
                    .collect()
            });
        check_result(got_recs, &case["recs"], &format!("{name}.recs"));

        assert_eq!(
            is_complete(&payload),
            case["complete"].as_bool().unwrap(),
            "{name}.complete"
        );

        for (key, want) in case["gate"].as_object().unwrap() {
            let (min_pop, include_adult) = {
                let parts: Vec<&str> = key.split('/').collect();
                (
                    parts[0].parse::<f64>().unwrap(),
                    parts[1].eq_ignore_ascii_case("true"), // Python's True/False
                )
            };
            match want {
                Value::Bool(b) => assert_eq!(
                    should_ingest(Some(&payload), min_pop, include_adult).unwrap(),
                    *b,
                    "{name}.gate[{key}]"
                ),
                // Python's should_ingest RAISED (e.g. float("abc")) —
                // the error text is pinned.
                Value::Object(o) => {
                    let got = should_ingest(Some(&payload), min_pop, include_adult)
                        .err()
                        .unwrap_or_else(|| panic!("{name}.gate[{key}]: no error, Python raised"));
                    assert_eq!(
                        err_string(&got),
                        o["error"].as_str().unwrap(),
                        "{name}.gate[{key}] error text"
                    );
                }
                other => panic!("{name}.gate[{key}]: malformed {other}"),
            }
        }
        // A missing payload is always rejected.
        assert!(
            !should_ingest(None, 0.0, false).unwrap(),
            "{name}: None payload"
        );
    }
}

#[test]
fn append_to_response_matches() {
    let doc = cases();
    let want = doc["append_to_response"].as_object().unwrap();
    assert_eq!(append_to_response("movie"), want["movie"].as_str().unwrap());
    assert_eq!(append_to_response("tv"), want["tv"].as_str().unwrap());
    assert_eq!(append_to_response("other"), want["other"].as_str().unwrap());
}
